// Premium icons in place of emoji. Every emoji listed in GI_DATA.map that appears in the page's text (menus, tabs,
// cards, toasts, chest reveals) is swapped for a game-icons.net glyph drawn with a dark ink outline and a glossy
// three-stop gradient, so icons look the same on every phone. Canvas text is untouched.
//   GI.svg('⭐') → icon HTML · GI.apply(element) → convert a subtree now · class "no-gi" opts a subtree out.
// Requires gicons-data.js (generated by scripts/make-gicons.js).
(function () {
  'use strict';
  const D = window.GI_DATA;
  if (!D) return;
  const PAL = {
    gold: ['#fff7c9', '#ffcc3a', '#c27400'], silver: ['#ffffff', '#c9d3e6', '#66748f'], red: ['#ffb8b8', '#ff4d5a', '#9e1220'],
    blue: ['#cde9ff', '#3d9bff', '#1546a8'], green: ['#cdffdb', '#3fd46e', '#127a37'], orange: ['#ffe3ad', '#ff8a1f', '#ad3b00'],
    cyan: ['#e2fdff', '#3fd8ff', '#0a6aa3'], purple: ['#eedaff', '#a66bff', '#5720b3'], pink: ['#ffd9f0', '#ff5cb8', '#9e1268'], brown: ['#ffdcae', '#c9813a', '#683610'],
  };
  const INK = '#1a0f2e';
  const strip = s => s.replace(/️/g, '');
  const MAP = {};
  for (const k in D.map) MAP[strip(k)] = D.map[k];
  // One hidden sprite holds the gradients and each glyph once; icons are cheap <use> references to it.
  let sprite = null;
  const made = {};
  function ensure(name) {
    if (!sprite) {
      sprite = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      sprite.setAttribute('aria-hidden', 'true');
      sprite.style.cssText = 'position:absolute;width:0;height:0;overflow:hidden';
      let defs = '';
      for (const p in PAL) {
        const c = PAL[p];
        defs += '<linearGradient id="gip-' + p + '" x1="0" y1="0" x2="0.25" y2="1"><stop offset="0" stop-color="' + c[0] + '"/><stop offset=".45" stop-color="' + c[1] + '"/><stop offset="1" stop-color="' + c[2] + '"/></linearGradient>';
      }
      sprite.innerHTML = '<defs>' + defs + '</defs>';
      (document.body || document.documentElement).appendChild(sprite);
      const st = document.createElement('style');
      st.textContent = '.gi{display:inline-block;width:1.18em;height:1.18em;vertical-align:-.24em;line-height:1;flex:0 0 auto;filter:drop-shadow(0 .07em 0 rgba(0,0,0,.4))}' +
        '.gi svg{display:block;width:100%;height:100%;overflow:visible}';
      document.head.appendChild(st);
    }
    if (!made[name]) {
      made[name] = true;
      const sym = document.createElementNS('http://www.w3.org/2000/svg', 'symbol');
      sym.id = 'gis-' + name; sym.setAttribute('viewBox', '0 0 512 512');
      sym.innerHTML = D.paths[name];
      sprite.firstChild.appendChild(sym);
    }
  }
  function svg(emoji) {
    const m = MAP[strip(emoji)];
    if (!m) return emoji;
    const [name, pal] = m;
    ensure(name);
    const use = '<use href="#gis-' + name + '"/>';
    // Ink outline (stroked copy), then the gradient body, then a thin highlight rim offset upward.
    // Its own tag (not <i>/<span>): many badge/bar rules style "X i" or "X span" and grabbed the icon too (it vanished).
    return '<g-i class="gi" aria-hidden="true"><svg viewBox="-28 -28 568 568">' +
      '<g fill="' + INK + '" stroke="' + INK + '" stroke-width="46" stroke-linejoin="round">' + use + '</g>' +
      '<g fill="url(#gip-' + pal + ')">' + use + '</g>' +
      '<g fill="none" stroke="rgba(255,255,255,.55)" stroke-width="10" transform="translate(0,-6)" style="clip-path:inset(0 0 55% 0)">' + use + '</g></svg></g-i>';
  }
  const keys = Object.keys(MAP).filter(k => !/^[a-z]+:/.test(k)).sort((a, b) => b.length - a.length).map(k => k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const RE = new RegExp('(' + keys.join('|') + ')\\uFE0F?', 'gu');
  const SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, INPUT: 1, OPTION: 1, CANVAS: 1, svg: 1, SVG: 1 };
  function convertText(t) {
    const s = t.nodeValue;
    RE.lastIndex = 0;
    if (!s || !RE.test(s)) return;
    RE.lastIndex = 0;
    for (let p = t.parentNode; p; p = p.parentNode) {
      if (p.nodeType !== 1) break;
      if (SKIP[p.nodeName] || (p.classList && (p.classList.contains('no-gi') || p.classList.contains('gi')))) return;
    }
    const tmp = document.createElement('span');
    tmp.innerHTML = s.replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[c]).replace(RE, m => svg(m));
    const frag = document.createDocumentFragment();
    while (tmp.firstChild) frag.appendChild(tmp.firstChild);
    t.parentNode.replaceChild(frag, t);
  }
  function apply(root) {
    if (!root) return;
    if (root.nodeType === 3) return convertText(root);
    if (root.nodeType !== 1 || SKIP[root.nodeName]) return;
    const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), list = [];
    while (w.nextNode()) list.push(w.currentNode);
    list.forEach(convertText);
  }
  let pending = new Set(), queued = false;
  function flush() {
    queued = false;
    const s = pending; pending = new Set();
    s.forEach(n => { if (n.isConnected) apply(n); });
  }
  function start() {
    apply(document.body);
    new MutationObserver(recs => {
      for (const r of recs) {
        if (r.type === 'characterData') pending.add(r.target);
        else r.addedNodes.forEach(n => pending.add(n));
      }
      if (!queued && pending.size) { queued = true; Promise.resolve().then(flush); }
    }).observe(document.body, { childList: true, subtree: true, characterData: true });
  }
  if (document.body) start(); else addEventListener('DOMContentLoaded', start);
  window.GI = { svg, apply, has: e => !!MAP[strip(e)] };
})();
